import os
import re
import sys


def _minimal(lines):
    out = []
    blanks = 0
    for line in lines:
        if not line.strip():
            blanks += 1
            if blanks > 1:
                continue
        else:
            blanks = 0
            line = line.strip()
        out.append(line)
    while out and not out[-1].strip():
        out.pop()
    if in_body and not brace_lang:
        out.append(' '*(body_indent+4)+'// ... implementation')
    return out


def _aggressive(lines, ext):
    # Keep declarations and structural lines; replace function bodies with an ellipsis.
    out, depth, in_body = [], 0, False
    body_indent = 0
    decl = re.compile(r'^\s*(?:async\s+)?(?:def |class |fn |pub(?:\([^)]*\))?\s+fn |function\b|export\s+(?:default\s+)?(?:async\s+)?function|(?:export\s+)?(?:interface|type|enum|struct|trait)\b|(?:public|private|protected|static|final|abstract)\s+[^=;]+\([^;]*\)\s*\{)')
    brace_lang = ext in ('.rs','.js','.jsx','.ts','.tsx','.go','.c','.h','.cpp','.java')
    for line in lines:
        s=line.strip()
        if in_body:
            if brace_lang:
                depth += line.count('{')-line.count('}')
                if depth <= 0:
                    out.append(' '*max(0,len(line)-len(line.lstrip()))+'... }')
                    in_body=False
                continue
            else:
                indent=len(line)-len(line.lstrip())
                if not s or indent>body_indent:
                    continue
                out.append(' '*(body_indent+4)+'// ... implementation')
                in_body=False
        if decl.match(line):
            if brace_lang and '{' in line and '}' not in line:
                out.append(line[:line.index('{')].rstrip()+' { ... }')
                depth=1; in_body=True
            elif not brace_lang and line.rstrip().endswith(':'):
                out.append(line)
                if not s.startswith('class '):
                    body_indent=len(line)-len(line.lstrip()); in_body=True
            else: out.append(line)
        elif s.startswith(('struct ','class ','interface ','enum ')) or s in ('{','}'):
            out.append(line)
    return out


def run_read(args):
    level='none'; max_lines=None; tail=None; numbers=False; files=[]
    i=0
    while i<len(args):
        a=args[i]
        if a in ('-l','--level') and i+1<len(args): level=args[i+1]; i+=2; continue
        if a in ('-m','--max-lines') and i+1<len(args):
            try: max_lines=max(0,int(args[i+1]))
            except ValueError: pass
            i+=2; continue
        if a=='--tail-lines' and i+1<len(args):
            try: tail=max(0,int(args[i+1]))
            except ValueError: pass
            i+=2; continue
        if a in ('-n','--line-numbers'): numbers=True
        elif a in ('-h','--help'):
            print('Read file with intelligent filtering\n\nUsage: executable read [OPTIONS] <FILES>...'); return 0
        elif a.startswith('-') and a not in ('-',): pass
        else: files.append(a)
        i+=1
    if not files: files=['-']
    chunks=[]; rc=0
    for path in files:
        try:
            raw=sys.stdin.read() if path=='-' else open(path,encoding='utf-8',errors='replace').read()
        except OSError as e:
            print(f'cat: {path}: {e.strerror} (os error {e.errno})',file=sys.stderr); rc=1; continue
        lines=raw.splitlines()
        if raw.endswith('\n') and lines==[]: lines=['']
        if level=='minimal': lines=_minimal(lines)
        elif level=='aggressive': lines=_aggressive(lines,os.path.splitext(path)[1].lower())
        if tail is not None: lines=lines[-tail:] if tail else []
        omitted=max(0,len(lines)-(max_lines or 0)) if max_lines is not None else 0
        if max_lines is not None and len(lines)>max_lines:
            n=max(0,max_lines-1); shown=lines[:n]
            marker=f'[{len(lines)-n} more lines]'
            lines=shown+[marker]
        if numbers:
            start=max(1,len(lines)-tail+1) if tail is not None else 1
            lines=[f'{start+j} │ {x}' for j,x in enumerate(lines)]
        chunks.append('\n'.join(lines))
    sys.stdout.write('\n'.join(chunks))
    if chunks and (raw.endswith('\n') if files[-1]!='-' else True): sys.stdout.write('\n')
    return rc

