import os, sys, fnmatch, subprocess

def run_ls(args):
    paths=[x for x in args if not x.startswith('-')] or ['.']
    show_all=any('a' in x[1:] for x in args if x.startswith('-'))
    long_mode=any('l' in x[1:] for x in args if x.startswith('-'))
    for path in paths:
        try: entries=list(os.scandir(path)) if os.path.isdir(path) else []
        except OSError as e:
            print(f'ls: {path}: {e.strerror}',file=sys.stderr); continue
        if os.path.isdir(path):
            names=[x for x in entries if show_all or not x.name.startswith('.')]
        else:
            names=[]
            if os.path.exists(path):
                class Entry:
                    name=os.path.basename(path)
                    def is_dir(self,follow_symlinks=False): return os.path.isdir(path)
                    @property
                    def path(self): return path
                names=[Entry()]
            else:
                print(f'ls: {path}: No such file or directory',file=sys.stderr); continue
        dirs=[]; files=[]
        for e in names:
            try:
                isdir=e.is_dir(follow_symlinks=False)
                size=os.path.getsize(e.path)
                if isdir: dirs.append(e.name+'/')
                elif long_mode: files.append(f'{e.name}  {size/1024:.1f}K')
            except OSError:
                if long_mode: files.append(e.name)
        if not os.path.isdir(path):
            print(os.path.basename(path)); continue
        if dirs: print('\n'.join(sorted(dirs)))
        if files: print('\n'.join(sorted(files)))
    return 0

def run_find(args):
    # The shorthand `find '*.rs' .` and native `find . -name '*.rs'` share output.
    args=list(args)
    if args and ('*' in args[0] or '?' in args[0]) and (len(args)==1 or not args[1].startswith('-')):
        pattern=args.pop(0); root=args.pop(0) if args and not args[0].startswith('-') else '.'
        args=[root,'-type','f','-name',pattern]+args
    roots=[x for x in args if not x.startswith('-') and os.path.isdir(x)]
    root=roots[0] if roots else '.'
    cp=subprocess.run(['find']+args,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
    if cp.stderr: sys.stderr.write(cp.stderr)
    groups={}; files=[]
    for line in cp.stdout.splitlines():
        p=line.rstrip('/')
        if not os.path.isfile(p): continue
        rel=os.path.relpath(p,root) if os.path.isdir(root) else p
        parent=os.path.dirname(rel)
        parent='./' if parent in ('','.') else parent.rstrip('/')+'/'
        groups.setdefault(parent,[]).append(os.path.basename(p)); files.append(p)
    if not files:
        pattern=''
        for i,arg in enumerate(args[:-1]):
            if arg in ('-name','-iname','-path','-ipath'):
                pattern=args[i+1]; break
        if not pattern and args and ('*' in args[-1] or '?' in args[-1]): pattern=args[-1]
        print(f"0 for '{pattern}'" if pattern else '0 files')
        return cp.returncode
    print(f'{len(files)}F {len(groups)}D:\n')
    for parent,names in groups.items(): print(f'{parent} '+', '.join(names[:12])+(f', ...{len(names)-12} more' if len(names)>12 else ''))
    return cp.returncode

