"""JSON structure and compact-value renderer."""
import json
import re
import sys


def scalar(v, keys=False):
    if keys:
        if v is None: return "null"
        if isinstance(v, bool): return "bool"
        if isinstance(v, int): return "int"
        if isinstance(v, float): return "float"
        if isinstance(v, str): return "string"
    return json.dumps(v, ensure_ascii=False, separators=(",", ":"))


def render(v, indent=0, depth=5, keys=False, level=0, top=False):
    pad = " " * indent
    if isinstance(v, dict):
        if level > depth and not top:
            return "..."
        if not v: return "{}"
        lines = ["{"]
        ordered = sorted(v)
        for ix, k in enumerate(ordered):
            val = v[k]
            key = k
            if isinstance(val, (dict, list)):
                rendered = render(val, indent+2, depth, keys, level+1)
                lines.append(" "*(indent+2) + key + ":")
                parts = rendered.splitlines()
                if parts:
                    lines.append(" "*(indent+2) + parts[0])
                    lines.extend(parts[1:])
            else:
                lines.append(" "*(indent+2) + key + ": " + scalar(val, keys))
            if keys and not isinstance(val, (dict, list)) and ix < len(ordered)-1:
                lines[-1] += ","
        lines.append(pad + "}")
        return "\n".join(lines)
    if isinstance(v, list):
        if not v: return "[]"
        if level > depth:
            return "..."
        if keys and isinstance(v[0], dict):
            body = render(v[0], indent+2, depth, keys, level+1)
            parts = body.splitlines()
            parts[-1] += f"] ({len(v)})"
            return "[" + "\n".join(parts)
        if all(not isinstance(x, (dict,list)) for x in v):
            if keys:
                return "[" + scalar(v[0], True) + f"] ({len(v)})"
            return json.dumps(v, ensure_ascii=False, separators=(", ", ": "))
        lines = ["["]
        for item in v:
            itemstr = render(item, indent+2, depth, keys, level+1)
            parts = itemstr.splitlines()
            lines.append(" "*(indent+2) + parts[0])
            lines.extend(parts[1:])
            lines[-1] += ","
        lines.append(pad + "]")
        if keys and v and isinstance(v[0], dict):
            lines[-1] += f" ({len(v)})"
        return "\n".join(lines)
    return scalar(v, keys)


def run_json(args):
    if any(a in ("-h", "--help") for a in args):
        print('Show JSON (compact values by default, or keys-only with --keys-only)\n\nUsage: executable json [OPTIONS] <FILE>\n\nArguments:\n  <FILE>  JSON file\n\nOptions:\n  -d, --depth <DEPTH>  Max depth [default: 5]\n      --keys-only      Show keys only (strip all values, show structure)\n  -v, --verbose...     Verbosity level (-v, -vv, -vvv)\n      --ultra-compact  Ultra-compact mode: ASCII icons, inline format (Level 2 optimizations)\n      --skip-env       Set SKIP_ENV_VALIDATION=1 for child processes (Next.js, tsc, lint, prisma)\n  -h, --help           Print help')
        return 0
    path = None
    keys = False
    depth = 5
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--keys-only": keys = True
        elif a in ("-d", "--depth") and i+1 < len(args):
            i += 1
            try: depth = max(0, int(args[i]))
            except ValueError: pass
        elif a.startswith("--depth="):
            try: depth = max(0, int(a.split("=",1)[1]))
            except ValueError: pass
        elif not a.startswith("-"): path = a
        i += 1
    if path is None:
        print("rtk: error: the following required arguments were not provided:\n  <FILE>", file=sys.stderr)
        return 2
    try:
        with open(path, encoding="utf-8") as f: value = json.load(f)
    except OSError as exc:
        label = "No such file or directory" if isinstance(exc, FileNotFoundError) else "Permission denied"
        print(f"rtk: Failed to read file: {path}: {label} (os error {exc.errno})", file=sys.stderr)
        return 1
    except json.JSONDecodeError as exc:
        message = exc.msg
        column = exc.colno
        try:
            with open(path, encoding="utf-8") as f: source = f.read()
        except OSError:
            source = ""
        if "Expecting property name enclosed in double quotes" in message:
            message = "key must be a string"
        elif "Extra data" in message:
            message = "trailing characters"
        elif "Expecting ':' delimiter" in message:
            message = "expected " + chr(96) + ":" + chr(96)
        elif "Expecting ',' delimiter" in message:
            stripped = source.rstrip()
            if stripped.startswith("{") and not stripped.endswith("}"):
                message = "EOF while parsing an object"
                column = len(source)
            elif stripped.startswith("[") and not stripped.endswith("]"):
                message = "EOF while parsing an array"
                column = len(source)
            else:
                message = "expected " + chr(96) + "," + chr(96) + " or " + chr(96) + "}" + chr(96)
        elif "Expecting value" in message:
            if re.search(r",\s*[}\]]", source):
                message = "trailing comma"
            elif source.strip() and not source.lstrip().startswith(("{", "[", '"')) and source.strip() not in ("true", "false", "null"):
                message = "expected ident"
                column += 1
            else:
                message = "expected value"
        elif "Unterminated string" in message:
            message = "EOF while parsing a string"
        print(f"rtk: Failed to parse JSON: {message} at line {exc.lineno} column {column}", file=sys.stderr)
        return 1
    print(render(value, depth=depth, keys=keys, top=True))
    return 0

